package sigepac.poo.infraestructura.persistencia;
import sigepac.poo.dominio.repositorios.IRepositorioCuentaUsuario;import sigepac.poo.dominio.entidades.CuentaUsuario;import sigepac.poo.dominio.objetos_valor.CorreoElectronico;import sigepac.poo.infraestructura.ConexionPoo;import java.sql.*;import java.util.*;
/** Adaptador JDBC de cuentas; mantiene el nombre histórico de la clase por compatibilidad. */
public class RepositorioCuentaUsuarioJdbc implements IRepositorioCuentaUsuario {
 private CuentaUsuario map(ResultSet r)throws SQLException{return new CuentaUsuario(r.getInt("id_cuenta"),r.getString("nombre"),r.getString("apellido"),new CorreoElectronico(r.getString("correo")),r.getString("contrasena_hash"),r.getString("rol"),r.getString("telefono"));}
 public CuentaUsuario buscarPorCorreo(CorreoElectronico correo){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("SELECT * FROM oop_cuentas_usuario WHERE correo=?")){p.setString(1,correo.getValor());try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public CuentaUsuario buscarPorId(int id){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("SELECT * FROM oop_cuentas_usuario WHERE id_cuenta=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public List<CuentaUsuario> obtenerTodos(){List<CuentaUsuario>a=new ArrayList<>();try(Connection c=ConexionPoo.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM oop_cuentas_usuario ORDER BY id_cuenta")){while(r.next())a.add(map(r));return a;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public int guardar(CuentaUsuario u){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("INSERT INTO oop_cuentas_usuario(nombre,apellido,correo,contrasena_hash,rol,telefono) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,u.getNombre());p.setString(2,u.getApellido());p.setString(3,u.getCorreo().getValor());p.setString(4,u.getContrasenaHash());p.setString(5,u.getRol());p.setString(6,u.getTelefono());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);throw new SQLException("Falta id generado");}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public boolean eliminar(int id){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("DELETE FROM oop_cuentas_usuario WHERE id_cuenta=?")){p.setInt(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
}
